# ---------------------------------------------------------------------------
# 1. basis states
# ---------------------------------------------------------------------------

def occ(i, m, order=LSB):
    """Occupation tuple (n_0, ..., n_{m-1}) of basis index i (descent-lift occ is order=MSB)."""
    if order == LSB:
